def is_undulating(n):
    """Write a function to check whether the given number is undulating or not.

    A number is undulating when it has at least three digits and its
    digits alternate between exactly two different digits, i.e. it has
    the form ``ababab...`` (for example, ``1212121``). Integers and
    strings of decimal digits are accepted; anything else, numbers
    with fewer than three digits, and negative numbers are not
    undulating.
    """
    if isinstance(n, bool):
        return False
    if isinstance(n, int):
        if n < 0:
            return False
        digits = str(n)
    elif isinstance(n, str):
        digits = n.strip()
        if not digits or not all("0" <= char <= "9" for char in digits):
            return False
    else:
        return False

    if len(digits) < 3:
        return False
    if digits[0] == digits[1]:
        return False
    return all(char == digits[index % 2] for index, char in enumerate(digits))
